//! Shared harness: a service in a temporary directory with a manual clock,
//! driven in-process through its router. Every credential is generated by
//! the test itself.
#![allow(dead_code)]
use axum::body::Body;
use axum::http::{HeaderMap, Method, Request, StatusCode};
use axum::Router;
use http_body_util::BodyExt;
use serde_json::{json, Value};
use std::sync::Arc;
use tower::ServiceExt;
use weave_engine::{ManualClock, TrustedClock};
use weave_service::log::{Logger, MemorySink};
use weave_service::{Limits, Service};

pub const START_MS: i64 = 1_800_000_000_000;

pub struct Harness {
    pub dir: tempfile::TempDir,
    pub service: Service,
    pub clock: Arc<ManualClock>,
    pub log: MemorySink,
    router: Router,
}

pub struct Reply {
    pub status: StatusCode,
    pub headers: HeaderMap,
    pub bytes: Vec<u8>,
    pub json: Value,
}

impl Reply {
    pub fn code(&self) -> &str {
        self.json["error"]["code"].as_str().unwrap_or("")
    }
}

impl Harness {
    pub fn new() -> Self {
        Self::with_limits(Limits::default())
    }
    pub fn with_limits(limits: Limits) -> Self {
        let dir = tempfile::tempdir().unwrap();
        let clock = Arc::new(ManualClock::new(START_MS));
        let log = MemorySink::default();
        let service =
            Service::open(dir.path(), clock.clone(), limits, Logger::new(log.clone())).unwrap();
        let router = service.router();
        Self {
            dir,
            service,
            clock,
            log,
            router,
        }
    }
    pub fn now(&self) -> i64 {
        self.clock.unix_millis().unwrap()
    }
    pub fn advance(&self, millis: i64) {
        self.clock.set(self.now() + millis);
    }
    /// Create a tenant whose first administrator is `admin`; returns the
    /// administrator's bootstrap token.
    pub fn tenant(&self, tenant: &str, admin: &str) -> String {
        self.advance(10);
        self.service.create_tenant(tenant, admin).unwrap().token
    }
    pub async fn send(
        &self,
        method: Method,
        path: &str,
        token: Option<&str>,
        body: Option<Value>,
    ) -> Reply {
        let bytes = body.map(|b| serde_json::to_vec(&b).unwrap());
        self.send_raw(method, path, token.map(|t| format!("Bearer {t}")), bytes)
            .await
    }
    pub async fn send_raw(
        &self,
        method: Method,
        path: &str,
        authorization: Option<String>,
        body: Option<Vec<u8>>,
    ) -> Reply {
        self.advance(10);
        let mut request = Request::builder().method(method).uri(path);
        if let Some(value) = authorization {
            request = request.header("authorization", value);
        }
        let request = match body {
            Some(bytes) => request
                .header("content-type", "application/json")
                .body(Body::from(bytes))
                .unwrap(),
            None => request.body(Body::empty()).unwrap(),
        };
        self.request(request).await
    }
    /// Send a request built by the test, with any headers.
    pub async fn request(&self, request: Request<Body>) -> Reply {
        let response = self.router.clone().oneshot(request).await.unwrap();
        let status = response.status();
        let headers = response.headers().clone();
        let bytes = response
            .into_body()
            .collect()
            .await
            .unwrap()
            .to_bytes()
            .to_vec();
        let json = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
        Reply {
            status,
            headers,
            bytes,
            json,
        }
    }
    pub async fn get(&self, path: &str, token: &str) -> Reply {
        self.send(Method::GET, path, Some(token), None).await
    }
    pub async fn post(&self, path: &str, token: &str, body: Value) -> Reply {
        self.send(Method::POST, path, Some(token), Some(body)).await
    }
    pub async fn registry(&self, token: &str, changes: Value) -> Reply {
        let reply = self
            .post("/v1/registry", token, json!({"changes": changes}))
            .await;
        reply
    }
    /// Issue a token for `principal` through the API, as an administrator.
    pub async fn token_for(&self, admin: &str, principal: &str) -> String {
        let reply = self
            .post("/v1/tokens", admin, json!({"principal": principal}))
            .await;
        assert_eq!(reply.status, StatusCode::CREATED, "{}", reply.json);
        reply.json["token"].as_str().unwrap().to_string()
    }
    pub async fn ids(&self, token: &str, count: usize) -> Vec<String> {
        let reply = self.post("/v1/ids", token, json!({"count": count})).await;
        assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
        reply.json["ids"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect()
    }
    pub async fn execute(&self, token: &str, commands: Value) -> Reply {
        self.post(
            "/v1/execute",
            token,
            json!({"version": weave_contract::VERSION, "commands": commands}),
        )
        .await
    }
    pub async fn write(&self, token: &str, graph: &str, facts: Vec<Value>) -> Reply {
        let changes: Vec<Value> = facts
            .into_iter()
            .map(|f| json!({"change": "assert", "fact": f}))
            .collect();
        self.execute(
            token,
            json!([{"op": "write", "graph_id": graph, "changes": changes}]),
        )
        .await
    }
    pub async fn query(&self, token: &str, graph: &str) -> Reply {
        self.execute(
            token,
            json!([{"op": "query", "query": {"graph_id": graph}}]),
        )
        .await
    }
    pub async fn audit_facts(&self, auditor: &str, graph: &str, fact: &str) -> Vec<Value> {
        let reply = self
            .get(
                &format!("/v1/audit/facts?graph_id={graph}&fact_id={fact}"),
                auditor,
            )
            .await;
        assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
        reply.json["accesses"].as_array().unwrap().clone()
    }
    pub async fn audit_entries(&self, auditor: &str) -> Vec<Value> {
        let reply = self.get("/v1/audit?limit=1000", auditor).await;
        assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
        reply.json["entries"].as_array().unwrap().clone()
    }
}

pub fn node(id: &str, readers: &[&str], groups: &[&str]) -> Value {
    let mut node = json!({"kind": "node", "id": id, "entity_id": format!("E-{id}"), "space_id": "s",
        "properties": {"label": id}});
    if !readers.is_empty() {
        node["readers"] = json!(readers);
    }
    if !groups.is_empty() {
        node["reader_groups"] = json!(groups);
    }
    node
}

pub fn edge(id: &str, from: &str, to: &str, readers: &[&str]) -> Value {
    let mut edge = json!({"kind": "edge", "id": id, "predicate": "weave:related", "from": from,
        "to": to, "valid_time": {"start": 0}});
    if !readers.is_empty() {
        edge["readers"] = json!(readers);
    }
    edge
}

/// Node IDs of the first result of an execute reply.
pub fn node_ids(reply: &Reply) -> Vec<String> {
    let mut out: Vec<String> = reply.json["results"][0]["result"]["graph"]["nodes"]
        .as_array()
        .unwrap_or(&vec![])
        .iter()
        .map(|n| n["id"].as_str().unwrap().to_string())
        .collect();
    out.sort();
    out
}

/// Standard tenant: administrator `root`, users alice and bob, group `team`
/// with alice. Returns (root, alice, bob) tokens.
pub async fn standard_tenant(h: &Harness, tenant: &str) -> (String, String, String) {
    let root = h.tenant(tenant, "root");
    let reply = h
        .registry(
            &root,
            json!([
                {"change": "add_principal", "id": "alice", "kind": "user"},
                {"change": "add_principal", "id": "bob", "kind": "user"},
                {"change": "add_principal", "id": "team", "kind": "group"},
                {"change": "add_member", "group": "team", "member": "alice"}
            ]),
        )
        .await;
    assert_eq!(reply.status, StatusCode::OK, "{}", reply.json);
    let alice = h.token_for(&root, "alice").await;
    let bob = h.token_for(&root, "bob").await;
    (root, alice, bob)
}
